changeSet.sql:
CREATE TABLE IF NOT EXISTS document.witness_requests ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, contract_id UUID NOT NULL, witness_id UUID NOT NULL, status VARCHAR(50), created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP );
-- Mavjud guvohlarni (status bilan) witness_requests'ga ko'chiramiz. INSERT INTO document.witness_requests (id, contract_id, witness_id, status, created_date, last_modified_date) SELECT id, contract_id, witness_id, status, created_date, last_modified_date FROM document.witnesses ON CONFLICT (id) DO NOTHING;
-- witnesses endi faqat qabul qilingan guvohlar; qolganlari o'chadi, status ustuni drop. DELETE FROM document.witnesses WHERE status IS DISTINCT FROM 'ACCEPTED'; ALTER TABLE document.witnesses DROP COLUMN IF EXISTS status;
